function normalize(input) {
  if (input === null || typeof input !== 'object' || Array.isArray(input)) throw new TypeError('Expected recipe');
  const keys = Object.keys(input);
  if (keys.length !== 3 || !keys.includes('name') || !keys.includes('servings') || !keys.includes('vegetarian')) {
    throw new TypeError('Unexpected recipe shape');
  }
  if (typeof input.name !== 'string' || !Number.isInteger(input.servings) || typeof input.vegetarian !== 'boolean') {
    throw new TypeError('Invalid recipe values');
  }
  const name = input.name.trim();
  if (name.length === 0 || input.servings < 1 || input.servings > 100) throw new RangeError('Recipe value out of range');
  return { name, servings: input.servings, vegetarian: input.vegetarian };
}

function createRecipeBook() {
  const recipes = new Map();
  let sequence = 1;
  const copy = (recipe) => ({ ...recipe });
  const checkKey = (key) => {
    if (typeof key !== 'string') throw new TypeError('Key must be a string');
  };

  return {
    add(input) {
      const key = `r${sequence++}`;
      const recipe = { key, ...normalize(input) };
      recipes.set(key, recipe);
      return copy(recipe);
    },
    list() {
      return Array.from(recipes.values());
    },
    get(key) {
      checkKey(key);
      return recipes.has(key) ? copy(recipes.get(key)) : null;
    },
    replace(key, input) {
      checkKey(key);
      const normalized = normalize(input);
      if (!recipes.has(key)) return null;
      const recipe = { key, ...normalized };
      recipes.set(key, recipe);
      return copy(recipe);
    },
    remove(key) {
      checkKey(key);
      return recipes.delete(key);
    }
  };
}

module.exports = { createRecipeBook };

