'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createRecipeBook']);
const { createRecipeBook } = api;
assert.equal(typeof createRecipeBook, 'function');

const book = createRecipeBook();
assert.deepStrictEqual(Object.keys(book), ['add', 'list', 'get', 'replace', 'remove']);
assert.deepStrictEqual(book.list(), []);
assert.strictEqual(book.get('r1'), null);
assert.equal(book.remove('r1'), false);

const input = Object.freeze({ name: '  Lentil Soup  ', servings: 4, vegetarian: true });
const added = book.add(input);
assert.deepStrictEqual(added, { key: 'r1', name: 'Lentil Soup', servings: 4, vegetarian: true });
assert.deepStrictEqual(input, { name: '  Lentil Soup  ', servings: 4, vegetarian: true });
const second = book.add(Object.freeze({ name: 'Egg Curry', servings: 1, vegetarian: false }));
assert.deepStrictEqual(second, { key: 'r2', name: 'Egg Curry', servings: 1, vegetarian: false });
assert.deepStrictEqual(book.list(), [added, second]);

const listA = book.list();
const listB = book.list();
assert.notStrictEqual(listA, listB);
assert.notStrictEqual(listA[0], listB[0]);
listA[0].name = 'Tampered';
listA.push({});
added.name = 'Also tampered';
assert.deepStrictEqual(book.get('r1'), { key: 'r1', name: 'Lentil Soup', servings: 4, vegetarian: true });
const getA = book.get('r1');
const getB = book.get('r1');
assert.notStrictEqual(getA, getB);

const replacementInput = Object.freeze({ name: '  Tomato Soup ', servings: 100, vegetarian: true });
const replacement = book.replace('r1', replacementInput);
assert.deepStrictEqual(replacement, { key: 'r1', name: 'Tomato Soup', servings: 100, vegetarian: true });
assert.deepStrictEqual(replacementInput, { name: '  Tomato Soup ', servings: 100, vegetarian: true });
assert.deepStrictEqual(book.list(), [replacement, second]);
assert.strictEqual(book.replace('missing', { name: 'Valid', servings: 2, vegetarian: true }), null);
assert.equal(book.remove('r1'), true);
assert.equal(book.remove('r1'), false);
assert.deepStrictEqual(book.list(), [second]);
assert.deepStrictEqual(
  book.add({ name: 'Third', servings: 2, vegetarian: true }),
  { key: 'r3', name: 'Third', servings: 2, vegetarian: true }
);

const other = createRecipeBook();
assert.deepStrictEqual(other.list(), []);
assert.deepStrictEqual(
  other.add({ name: 'Independent', servings: 1, vegetarian: true }),
  { key: 'r1', name: 'Independent', servings: 1, vegetarian: true }
);

for (const key of [null, undefined, 1, {}, []]) {
  assert.throws(() => book.get(key), TypeError);
  assert.throws(() => book.remove(key), TypeError);
  assert.throws(() => book.replace(key, { name: 'Valid', servings: 1, vegetarian: true }), TypeError);
}
for (const bad of [
  null, [], 'recipe', {},
  { name: 'A', servings: 1 },
  { name: 'A', servings: 1, vegetarian: true, extra: 1 },
  { name: 3, servings: 1, vegetarian: true },
  { name: 'A', servings: 1.5, vegetarian: true },
  { name: 'A', servings: '1', vegetarian: true },
  { name: 'A', servings: 1, vegetarian: 1 }
]) assert.throws(() => book.add(bad), TypeError);
for (const bad of [
  { name: '', servings: 1, vegetarian: true },
  { name: '   ', servings: 1, vegetarian: true },
  { name: 'A', servings: 0, vegetarian: true },
  { name: 'A', servings: 101, vegetarian: true }
]) assert.throws(() => book.add(bad), RangeError);

